'use strict';(()=>{const data=[
{id:'emeraude',name:'Émeraude Signature',family:'sport',familyName:'Sport chic',tone:'green',shape:'angular',strap:'steel',description:'Cadran vert profond, lignes structurées et bracelet acier intégré.',tags:['Vert profond','Acier argenté','Sport chic']},
{id:'glacier',name:'Glacier Signature',family:'sport',familyName:'Sport chic',tone:'blue',shape:'angular',strap:'steel',description:'La même silhouette élégante, avec un cadran bleu glacier lumineux.',tags:['Bleu glacier','Acier argenté','Sport chic']},
{id:'minuit',name:'Minuit Classique',family:'classic',familyName:'Classique',tone:'black',shape:'round',strap:'steel',description:'Noir profond et index discrets dans un boîtier aux proportions sobres.',tags:['Noir','Acier','Classique']},
{id:'azur',name:'Azur Classique',family:'classic',familyName:'Classique',tone:'teal',shape:'round',strap:'steel',description:'Bleu nuit et éclats argentés pour un style intemporel.',tags:['Bleu nuit','Métal','Classique']},
{id:'argent',name:'Argent Minimal',family:'minimal',familyName:'Minimaliste',tone:'ivory',shape:'thin',strap:'mesh',description:'Cadran clair et bracelet maille fine au caractère discret.',tags:['Cadran clair','Maille acier','Épurée']},
{id:'sable',name:'Sable Minimal',family:'minimal',familyName:'Minimaliste',tone:'sand',shape:'thin',strap:'leather',description:'Nuances champagne et bracelet sombre pour une allure habillée.',tags:['Champagne','Bracelet sombre','Habillée']}
];const $=(id)=>document.getElementById(id);const grid=$('styleGrid'),count=$('favCount'),res=$('resultCount'),sum=$('favSummary'),copy=$('copyFav'),feedback=$('copyFeedback'),empty=$('emptyFavourites');if(!grid||!count||!res||!sum||!copy||!empty)return;const key='atelier-style-favs-v1';let fav=new Set(),filter='all';try{const x=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(x))fav=new Set(x.filter(id=>data.some(c=>c.id===id)))}catch(_){ }const make=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n};function card(c){const item=make('article','sel-card'),art=make('div','sel-art '+c.tone);art.setAttribute('role','img');art.setAttribute('aria-label','Illustration fictive du style '+c.name);const band=make('div','sel-strap '+(c.strap==='steel'?'':c.strap));const watch=make('div','sel-watch '+(c.shape==='round'?'':c.shape));watch.append(make('span','sel-center'));art.append(band,watch,make('span','sel-tag','CONCEPT NON COMMERCIALISÉ'));const box=make('div','sel-card-body');box.append(make('p','sel-category',c.familyName),make('h3','',c.name),make('p','desc',c.description));const tags=make('div','sel-tags');c.tags.forEach(t=>tags.append(make('span','',t)));box.append(tags);const btn=make('button','sel-save',fav.has(c.id)?'✓ Retirer des favoris':'♡ Ajouter aux favoris');btn.type='button';btn.setAttribute('aria-pressed',String(fav.has(c.id)));btn.setAttribute('aria-label',(fav.has(c.id)?'Retirer des favoris : ':'Ajouter aux favoris : ')+c.name);btn.addEventListener('click',()=>{if(fav.has(c.id))fav.delete(c.id);else fav.add(c.id);try{localStorage.setItem(key,JSON.stringify([...fav]))}catch(_){ }feedback.textContent='';render()});box.append(btn);item.append(art,box);return item}function render(){const visible=data.filter(c=>filter==='all'||(filter==='saved'?fav.has(c.id):c.family===filter));grid.replaceChildren(...visible.map(card));empty.hidden=visible.length>0;count.textContent=String(fav.size);res.textContent=String(visible.length)+' inspiration'+(visible.length===1?'':'s');const chosen=data.filter(c=>fav.has(c.id));sum.textContent=chosen.length?chosen.map(c=>c.name).join(' · '):'Sélectionnez un ou plusieurs styles.';copy.disabled=fav.size===0;document.querySelectorAll('.sel-filter').forEach(b=>{const active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}document.querySelectorAll('.sel-filter').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter||'all';render()}));copy.addEventListener('click',async()=>{const chosen=data.filter(c=>fav.has(c.id));if(!chosen.length)return;const text='Sélection Atelier Montres (concepts) :\n'+chosen.map(c=>'- '+c.name+' : '+c.description).join('\n');try{if(!navigator.clipboard||!navigator.clipboard.writeText)throw Error('unavailable');await navigator.clipboard.writeText(text);feedback.textContent='Sélection copiée. Collez-la dans notre conversation.'}catch(_){feedback.textContent='Copie impossible dans ce navigateur : '+chosen.map(c=>c.name).join(', ')}});render()})();

/* Atelier Montres: indexable editorial pages, no third-party fonts or scripts. */
:root{color-scheme:light;--ink:#183229;--accent:#a08350;--paper:#f8f5ec;--line:#dfd7c8}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.wrap{width:min(1160px,calc(100% - 40px));margin-inline:auto}a{color:inherit;text-underline-offset:3px}a:focus-visible{outline:3px solid #b18c52;outline-offset:4px}.skip{position:absolute;top:-100px;left:14px;background:white;padding:10px;z-index:10}.skip:focus{top:10px}
.top{background:#172d25;color:#f8f2e5}.nav{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{text-decoration:none;font:400 26px/1.2 Georgia,serif;white-space:nowrap}.nav nav{display:flex;gap:24px;flex-wrap:wrap}.nav nav a{font-size:14px;text-decoration:none}.nav nav a:hover{text-decoration:underline}
.crumb{font-size:13px;color:#57695b;padding:24px 0}.watch{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,70px);align-items:center;padding:16px 0 64px}
.photo{min-height:350px;background:#f0ebe0;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden}.photo img{width:100%;height:auto;max-height:560px;aspect-ratio:1;object-fit:contain}
.photo:has(.watch-vector){display:flex;flex-direction:column;justify-content:center;gap:8px;padding:24px}
.watch-vector{width:min(100%,390px);margin:auto;min-height:330px;display:grid;place-items:center}
.watch-vector .am-watch-svg{width:100%;max-height:460px;display:block}
.watch-vector-note{font-size:12px;line-height:1.6;text-align:center;color:#4e5c51;max-width:350px;margin:auto}
@media(max-width:720px){.watch-vector{min-height:260px}.photo:has(.watch-vector){padding:12px}}.eyebrow{display:block;color:#74623d;letter-spacing:.13em;text-transform:uppercase;font-weight:700;font-size:12px}.intro h1,.editorial h1{font:400 clamp(35px,5.5vw,66px)/1.09 Georgia,serif;margin:18px 0}.intro .subtitle{font:italic 24px Georgia,serif;color:#566756}.lead{font-size:18px;line-height:1.85;color:#46584e}.tags{display:flex;flex-wrap:wrap;gap:7px;margin:24px 0}.tags span{padding:7px 12px;background:#ede6d6;font-size:12px;border:1px solid #e0d2b7}.disclosure{font-size:13px;color:#536159;line-height:1.7;border-left:3px solid var(--accent);padding-left:14px}
.primary,.secondary{display:inline-block;text-align:center;text-decoration:none;padding:15px 20px;margin:12px 12px 0 0;min-height:52px;font-weight:650;font-size:14px}.primary{background:#193629;color:#fff}.primary:hover{background:#285142}.secondary{border:1px solid #647765}.secondary:hover{background:#ece7dc}
.content{max-width:900px;padding:20px 0 90px}.content h2{font:400 clamp(26px,3vw,38px)/1.25 Georgia,serif;margin:44px 0 14px}.content p{line-height:1.9;color:#43584b}.content dl{border-top:1px solid var(--line)}.content dl>div{display:grid;grid-template-columns:45% 1fr;padding:14px 8px;border-bottom:1px solid var(--line)}.content dt{font-weight:650}.content dd{margin:0}
.related{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.related li{padding:16px;background:#fffefa;border:1px solid var(--line)}.related a{display:block;font-weight:700}.related span,.related small{font-size:13px;display:block;color:#617063;margin-top:6px}.editorial{max-width:1050px}.editorial>.lead{max-width:800px}footer{background:#172d25;color:#f4ead8;padding:50px 0;font-size:13px}footer strong{font:400 27px Georgia,serif}footer p{max-width:780px;color:#d4d9ce}
.seo-links{padding:72px 0;background:#eee9df;border-top:1px solid #e1d7c8}.seo-links h2{font:400 clamp(32px,4vw,48px) Georgia,serif;margin:15px 0}.seo-links>div>p{max-width:750px}.seo-links ul{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.seo-links li{background:#fffcf7;border:1px solid #e3daca;padding:16px;display:flex;flex-direction:column;gap:6px}.seo-links li a{font-weight:650;color:#203d2c}.seo-links li small{font-size:12px;color:#627063}.seo-links>div>p:last-child{margin-top:26px;font-weight:600}
@media(max-width:720px){.wrap{width:min(100% - 28px,1160px)}.nav{align-items:flex-start;flex-direction:column;padding:17px 0;gap:13px}.nav nav{gap:14px}.nav nav a{font-size:13px}.watch{grid-template-columns:1fr;padding-bottom:32px;gap:16px}.photo{min-height:260px}.photo img{max-height:390px}.related{grid-template-columns:1fr}.seo-links ul{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding-bottom:56px}.primary,.secondary{margin-right:0;width:100%}}
@media(max-width:430px){.seo-links ul{grid-template-columns:1fr}.intro h1,.editorial h1{font-size:35px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

/* Scrollable comparisons stay usable at Android widths and with keyboard navigation. */
.comparison-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;border:1px solid var(--line);background:#fffefb;margin:24px 0;scrollbar-color:#9c875e #f1ebe0}
.comparison-scroll:focus-visible{outline:3px solid #b18c52;outline-offset:3px}
.spec-matrix{border-collapse:collapse;min-width:650px;width:100%;font-size:14px;line-height:1.55;text-align:left}
.spec-matrix caption{caption-side:top;text-align:left;padding:16px;font:400 20px Georgia,serif;color:#253e2e}
.spec-matrix th,.spec-matrix td{padding:14px 15px;border-bottom:1px solid #e6ded0;vertical-align:top}
.spec-matrix th{font-weight:650;color:#203c2c}
.spec-matrix tbody tr:nth-child(odd){background:#f8f5ee}
.spec-matrix th:first-child{min-width:125px}
.spec-matrix a{color:#204f3c;text-decoration-thickness:1px}
@media(max-width:720px){.spec-matrix{font-size:13px}.spec-matrix th,.spec-matrix td{padding:12px}}

/* Browse-first editorial shortcuts immediately below the catalogue hero. */
.seo-guides{padding:70px 0 76px;background:#f4eee3;border-bottom:1px solid #ded2bf;color:#193226}
.seo-guides h2{font:400 clamp(34px,4.5vw,56px)/1.1 Georgia,serif;letter-spacing:-.025em;margin:0 0 15px}
.seo-guides-lead{max-width:800px;color:#5a6b60;line-height:1.75;margin-bottom:32px}
.seo-guide-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}
.seo-guide-grid article{background:#fffdf8;border:1px solid #e0d7c9;padding:clamp(19px,2.6vw,32px);min-width:0;display:flex;flex-direction:column;gap:8px}
.seo-guide-grid article>span{font-size:11px;letter-spacing:.11em;color:#856c46;font-weight:700}
.seo-guide-grid article h3{font:400 clamp(24px,2.8vw,32px)/1.15 Georgia,serif;margin:8px 0}
.seo-guide-grid article p{font-size:14px;line-height:1.75;color:#5c685f;flex:1}
.seo-guide-grid article a{font-size:13px;font-weight:700;text-decoration:underline;line-height:1.6;color:#204c39}
@media(max-width:820px){.seo-guide-grid{grid-template-columns:1fr}.seo-guide-grid article{padding:22px}.seo-guides{padding:54px 0}}

/* Product cards surface the full static comparison without changing their primary interactive route. */
.aff-card .am-card-seo-link{display:inline-block;margin:4px 20px 7px;color:#1e5441;font-size:12px;font-weight:700;text-underline-offset:3px;line-height:1.6}
.aff-card .am-card-seo-link:hover{color:#0b3425}

/* Editorial head-to-head comparisons: no third-party assets, keyboard-safe. */
.headtohead-home{background:#f4efe4;border-top:1px solid #e1d9cb}
.headtohead-home .seo-guide-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.headtohead-home .seo-guide-grid article{background:#fffdf8}
.headtohead{padding-bottom:60px}
.headtohead>.disclosure{max-width:900px}
.headtohead-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:32px 0 30px;align-items:stretch}
.headtohead-watch{display:flex;flex-direction:column;border:1px solid var(--line);background:#fffdf8;min-width:0}
.headtohead-watch-visual{display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 50% 40%,#fcfbf6,#eae8df 85%);border-bottom:1px solid var(--line)}
.headtohead-watch-visual .headtohead-photo{display:block;width:min(100%,360px);aspect-ratio:1;max-height:370px;object-fit:contain;filter:drop-shadow(0 12px 20px #18322722)}
.headtohead-watch-visual .watch-vector{margin:0 auto;min-height:250px;width:min(100%,320px)}
.headtohead-watch-visual .am-watch-svg{max-height:360px}
.headtohead-watch-body{display:flex;flex:1;flex-direction:column;padding:clamp(18px,2.8vw,30px)}
.headtohead-watch-body h2{font:400 clamp(26px,3vw,35px)/1.18 Georgia,serif;margin:12px 0 10px;overflow-wrap:anywhere}
.headtohead-watch-body>p{color:#516458;font-size:14px;line-height:1.75}
.headtohead-watch-evidence{margin-top:auto;padding-top:12px}
.headtohead-watch-evidence a{font-weight:700;color:#25513b}
.headtohead-watch-actions{display:flex;flex-wrap:wrap;gap:10px;padding-top:8px}
.headtohead-watch-actions .primary,.headtohead-watch-actions .secondary{flex:1 1 195px;margin:0;display:flex;align-items:center;justify-content:center}
.headtohead-watch-body>.headtohead-watch-legal{font-size:12px;margin-bottom:0}
.headtohead-evidence{max-width:none}
.headtohead-evidence>p{max-width:900px}
.headtohead-evidence .comparison-scroll{max-width:100%}
.headtohead-evidence .spec-matrix{min-width:580px}
.headtohead-evidence .comparison-different{background:#f5f0e3}
.headtohead-evidence .comparison-different th{border-left:3px solid #b39059}
.headtohead-choice{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin:22px 0 32px}
.headtohead-choice>div{padding:18px;background:#f1ece1;border:1px solid #e0d5c3}
.headtohead-choice h3{font:400 21px/1.25 Georgia,serif;margin:0 0 8px}
.headtohead-choice p{font-size:14px;margin:0;line-height:1.8}
@media(max-width:780px){.headtohead-grid,.headtohead-choice,.headtohead-home .seo-guide-grid{grid-template-columns:1fr}.headtohead-watch-visual .watch-vector{min-height:230px}.headtohead-watch-body{padding:20px}.headtohead-watch-actions a{width:100%}}
@media(prefers-reduced-motion:reduce){.headtohead a{scroll-behavior:auto}}

/* Genuine, indexable, user-first category collections. No CSS assets or
   scripts imported from competitors; all photos come from verified local ids. */
.seo-search-collections{padding:74px 0 83px;background:#e7ece5;border-block:1px solid #cdd8ce;color:#1c3b2a}
.seo-search-collections h2{font:400 clamp(32px,4vw,50px)/1.12 Georgia,serif;letter-spacing:-.035em;max-width:790px;margin:12px 0}
.seo-search-collections .wrap>p:not(.overline){max-width:750px;color:#536759;font-size:15px;line-height:1.8}
.seo-search-collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:28px}
.seo-search-collection-grid article{background:#fafaf5;border:1px solid #ced9cd;display:flex;flex-direction:column;gap:12px;min-width:0;padding:clamp(20px,2.8vw,34px)}
.seo-search-collection-grid article>span{color:#7e704e;font:700 10px/1.4 system-ui;letter-spacing:.11em}
.seo-search-collection-grid h3{font:400 clamp(24px,2.7vw,31px)/1.19 Georgia,serif;letter-spacing:-.025em;margin:0}
.seo-search-collection-grid p{font:400 13px/1.8 system-ui;color:#607163;flex:1;margin:0}
.seo-search-collection-grid a{display:inline-flex;align-items:center;min-height:44px;font:700 13px/1.4 system-ui;color:#1d5537;text-underline-offset:4px;margin-top:3px}
.seo-collection{padding-bottom:35px}
.seo-collection>h1{font:400 clamp(37px,5vw,61px)/1.12 Georgia,serif;letter-spacing:-.038em;max-width:950px;margin:13px 0 22px}
.seo-collection>.lead{max-width:940px}
.seo-collection>.disclosure{max-width:940px;font-size:12px;line-height:1.7;color:#566b5d;border-left:3px solid #b59867;background:#eeeae1;padding:14px 19px;margin:25px 0}
.seo-collection-overview{padding:34px 0 16px}
.seo-collection-overview>h2{font:400 clamp(30px,3.4vw,43px)/1.18 Georgia,serif;margin:0 0 12px}
.seo-collection-overview>p{color:#506457;max-width:770px;font-size:14px}
.seo-collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:22px}
.seo-collection-card{display:flex;flex-direction:column;min-width:0;background:#fffdf8;border:1px solid #ded6c6}
.seo-collection-picture{display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 40%,#fffefb,#e7e9df);min-height:250px;aspect-ratio:1.1;overflow:hidden;outline-offset:-3px}
.seo-collection-picture img{display:block;width:100%;height:100%;max-height:290px;object-fit:contain;padding:14px;mix-blend-mode:multiply}
.seo-collection-missing{font-size:12px;color:#647266;padding:24px;text-align:center}
.seo-collection-card-copy{display:flex;flex-direction:column;flex:1;padding:21px 22px 23px}
.seo-collection-maker{font-size:10px;font-weight:800;letter-spacing:.15em;text-transform:uppercase;color:#897351;margin:0}
.seo-collection-card h2{font:400 clamp(22px,2.4vw,30px)/1.18 Georgia,serif;overflow-wrap:anywhere;margin:9px 0 11px}
.seo-collection-card h2 a{text-decoration:none}
.seo-collection-card h2 a:hover{text-decoration:underline}
.seo-collection-card-copy>p:not(.seo-collection-maker){font:400 13px/1.7 system-ui;color:#57695c;flex:1}
.seo-collection-card dl{border-top:1px solid #ded9cd;padding:12px 0;margin:13px 0}
.seo-collection-card dl>div{display:flex;gap:12px;justify-content:space-between;font:400 12px/1.65 system-ui}
.seo-collection-card dl dt{color:#68766d}
.seo-collection-card dl dd{color:#2c4a36;font-weight:700;text-align:right;margin:0}
.seo-collection-actions{display:grid;grid-template-columns:1fr;gap:7px;margin-top:auto}
.seo-collection-actions a{display:flex;align-items:center;justify-content:center;text-align:center;min-height:44px;padding:10px 12px;font:700 12px/1.45 system-ui;color:#25503a;border:1px solid #c4d1c1;background:#f5f9f2;text-decoration:none}
.seo-collection-actions a:first-child{background:#214b34;color:white;border-color:#214b34}
.seo-collection-actions .seo-collection-merchant{background:#fffdf8;color:#37573f}
.seo-collection-actions a:hover{filter:brightness(.94)}
.seo-collection-evidence{padding-bottom:55px}
.seo-collection-evidence h2{font:400 29px/1.22 Georgia,serif;margin:32px 0 14px}
.seo-collection-evidence>p{max-width:980px}
@media(max-width:940px){.seo-search-collection-grid,.seo-collection-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){
 .seo-search-collections{padding:54px 0}
 .seo-search-collection-grid,.seo-collection-grid{grid-template-columns:1fr}
 .seo-search-collection-grid article{padding:22px}
 .seo-collection>h1{font-size:clamp(32px,8.5vw,44px)}
 .seo-collection-grid{gap:14px}
 .seo-collection-picture{max-height:350px}
 .seo-collection-card-copy{padding:20px}
 .seo-collection-overview{padding-top:18px}
}


/* Factual decision guidance + authentic local related-watch photography. */
.seo-buying-checks{border:1px solid #d8d2c4;background:#f1ede4;padding:clamp(20px,3.5vw,34px);margin:36px 0 44px}
.seo-buying-checks h2{margin:0 0 19px}
.seo-buying-checks ul{margin:0;padding-left:23px;display:grid;gap:12px;color:#354b3d;line-height:1.75}
.seo-buying-checks li::marker{color:#90754e}
.seo-buying-checks p{font-size:13px;line-height:1.7;margin:22px 0 0;color:#5a665b}
.seo-related-products{grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin-top:22px}
.seo-related-products li{padding:0;display:flex;flex-direction:column;min-width:0;background:#fffdf9}
.seo-related-products li>a{text-decoration:none;display:flex;flex-direction:column;flex:1}
.seo-related-visual{display:grid;place-items:center;background:radial-gradient(circle at 50% 38%,#fffefa,#e8e9e0);aspect-ratio:1.1;overflow:hidden}
.seo-related-photo{display:block;width:100%;height:100%;max-height:245px;object-fit:contain;padding:13px}
.seo-related-photo-placeholder{font-size:12px;color:#586e60;text-align:center;padding:18px}
.seo-related-products strong{display:block;padding:15px 15px 7px;font:400 clamp(18px,2vw,24px)/1.25 Georgia,serif;overflow-wrap:anywhere}
.seo-related-products small{padding:0 15px 18px;color:#576c5c;line-height:1.55;font-size:12px}
.seo-related-products a:hover strong{text-decoration:underline}
@media(max-width:780px){.seo-related-products{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:460px){.seo-related-products{grid-template-columns:1fr}.seo-related-photo{max-height:260px}}


/* Editorial method: transparent evidence and useful navigation. */
.seo-method-teaser{padding:65px 0;background:#192f27;color:#f7f2e8;border-top:1px solid #a79775}
.seo-method-teaser .eyebrow{color:#d9b980}
.seo-method-teaser h2{font:400 clamp(31px,4vw,46px)/1.15 Georgia,serif;max-width:760px;margin:16px 0}
.seo-method-teaser p:not(.eyebrow){max-width:740px;line-height:1.85;color:#e1e1d7}
.seo-method-teaser a{display:inline-flex;align-items:center;min-height:48px;color:#ffe3a7;font-weight:700;text-underline-offset:5px}
