'use strict';
/* Progressive enhancement on top of all 52 prerendered, crawlable cards. */
(() => {
  const $=id=>document.getElementById(id);
  const root=$('udGrid'),form=$('udFilters'),status=$('udCount'),empty=$('udEmpty');
  const compareStatus=$('udCompareStatus'),compareClear=$('udCompareClear'),compareTable=$('udCompareTable');
  const decisionForm=$('udDecisionForm'),decisionReset=$('udDecisionReset');
  const decisionEngine=window.AtelierAdvisorEngine;
  const tray=$('udCompareTray'),trayItems=$('udTrayItems'),trayCount=$('udTrayCount'),
    trayOpen=$('udTrayOpen'),trayClear=$('udTrayClear'),catalogue=document.querySelector('.ud-page');
  const viewTools=$('udViewTools'),viewCompact=$('udViewCompact'),viewLarge=$('udViewLarge');
  const favoriteTools=$('udFavoriteTools'),savedToggle=$('udSavedToggle'),
    savedCount=$('udSavedCount'),savedButtonLabel=$('udSavedButtonLabel');
  if(!root||!form||!status||!empty||!compareStatus||!compareClear||!compareTable
    ||!tray||!trayItems||!trayCount||!trayOpen||!trayClear||!catalogue
    ||!viewTools||!viewCompact||!viewLarge||!favoriteTools||!savedToggle||!savedCount||!savedButtonLabel)return;
  const cards=[...root.querySelectorAll('article.ud-card[data-id]')];
  const editorialOrder=new Map(cards.map((card,index)=>[card.dataset.id,index]));
  const node=(tag,text,cls)=>{
    const el=document.createElement(tag);
    if(text!==undefined&&text!==null)el.textContent=String(text);
    if(cls)el.className=cls;
    return el;
  };
  const normalized=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const controls={q:$('udSearch'),brand:$('udBrand'),style:$('udStyle'),
    movement:$('udMovement'),tier:$('udTier'),size:$('udSize'),visual:$('udVisual'),
    merchant:$('udMerchant'),sort:$('udSort')};
  const activeFilters=$('udActiveFilters'),activePills=$('udActiveFilterPills'),
    clearActive=$('udClearActiveFilters');
  const filterNames={q:'Recherche',brand:'Marque',style:'Style',movement:'Mouvement',
    tier:'Gamme',size:'Taille',visual:'Photo',merchant:'Marchand'};
  let watches=new Map(),selected=[],view='grid',currentSort=null,saved=new Set(),savedOnly=false;
  const validId=x=>typeof x==='string'&&/^[a-z0-9-]{4,64}$/.test(x);
  // Shared with the 15-watch comparison gallery: a watch saved on either
  // page must remain saved across the entire 52-watch catalogue.
  const FAVORITES_KEY='atelier-montres-multibrand-favorites-v1';
  const loadSaved=()=>{
    try{
      const values=JSON.parse(localStorage.getItem(FAVORITES_KEY)||'[]');
      return Array.isArray(values)?new Set(values.filter(validId).slice(0,100)):new Set();
    }catch(_){return new Set()}
  };
  const matchSize=(p,value)=>{
    if(value==='all')return true;
    const n=p?.diameterMm;
    if(value==='unknown')return n===null;
    if(typeof n!=='number'||!Number.isFinite(n))return false;
    if(value==='compact')return n<=38;
    if(value==='medium')return n>38&&n<=40;
    if(value==='large')return n>40;
    return false;
  };
  const params=new URLSearchParams(location.search);
  const prefKeys=['tier','style','movement','size'];
  const prefParam=key=>'pref'+key[0].toUpperCase()+key.slice(1);
  const prefControls={
    tier:$('udPrefTier'),style:$('udPrefStyle'),
    movement:$('udPrefMovement'),size:$('udPrefSize')
  };
  let decisionPrefs=decisionEngine?.choices(Object.fromEntries(
    prefKeys.map(key=>[key,params.get(prefParam(key))||'all'])))||null;
  if(decisionPrefs)for(const key of prefKeys){
    if(prefControls[key])prefControls[key].value=decisionPrefs[key];
  }
  const resetDecision=()=>{
    if(decisionEngine)decisionPrefs=decisionEngine.choices({});
    for(const key of prefKeys)if(prefControls[key])prefControls[key].value='all';
  };
  saved=loadSaved();
  savedOnly=params.get('saved')==='1';
  for(const [key,control] of Object.entries(controls)){
    const value=params.get(key);
    if(!value)continue;
    if(key==='q')control.value=value.slice(0,100);
    else if([...control.options].some(o=>o.value===value))control.value=value;
  }
  const persist=()=>{
    const query=new URLSearchParams();
    for(const [name,control] of Object.entries(controls)){
      const value=control.value;
      if(value&&(name==='q'||value!=='all')&&(name!=='sort'||value!=='essential'))
        query.set(name,value.slice(0,100));
    }
    if(selected.length)query.set('compare',selected.join(','));
    if(selected.length&&decisionPrefs){
      for(const key of prefKeys)if(decisionPrefs[key]!=='all')
        query.set(prefParam(key),decisionPrefs[key]);
    }
    if(savedOnly)query.set('saved','1');
    if(view==='large')query.set('view','large');
    const next=location.pathname+(query.size?'?'+query.toString():'')+location.hash;
    history.replaceState(null,'',next);
  };
  const reorderCards=mode=>{
    if(currentSort===mode)return;
    const tiers={essential:0,signature:1,prestige:2};
    // A verified deep link should always rank ahead of a generic search.
    const merchants={direct:0,awin:1,search:2,official:3};
    const rank=(p)=>merchants[p.merchantKind||'official'];
    const ordered=[...cards].sort((a,b)=>{
      const left=watches.get(a.dataset.id),right=watches.get(b.dataset.id);
      const original=editorialOrder.get(left.id)-editorialOrder.get(right.id);
      if(mode==='essential')return tiers[left.tier]-tiers[right.tier]
        ||Number(Boolean(right.photoUrl))-Number(Boolean(left.photoUrl))
        ||rank(left)-rank(right)||original;
      if(mode==='direct')return rank(left)-rank(right)
        ||tiers[left.tier]-tiers[right.tier]||original;
      if(mode==='photo')return Number(Boolean(right.photoUrl))-Number(Boolean(left.photoUrl))
        ||tiers[left.tier]-tiers[right.tier]||original;
      if(mode==='alpha')return (left.brand+' '+left.model).localeCompare(right.brand+' '+right.model,'fr')||original;
      return original;
    });
    root.replaceChildren(...ordered);
    currentSort=mode;
  };
  // The visible query must find exact references typed without punctuation,
  // e.g. "MDV107", "PD1701" or "skmei1251", as well as normal French text.
  const matchesText=(p,terms)=>{
    if(!terms.length)return true;
    const source=normalized([p.brand,p.model,p.id,p.description,p.lead,
      p.caseText,p.glass,p.water].filter(Boolean).join(' '));
    const compactModel=normalized([p.brand,p.model].join(' ')).replace(/\s+/g,'');
    const compactReference=normalized([p.model,p.id].join(' ')).replace(/\s+/g,'');
    return terms.every(term=>source.includes(term)
      ||compactModel.includes(term)||compactReference.includes(term));
  };
  let activeFilterSignature='';
  const updateActiveFilters=()=>{
    if(!activeFilters||!activePills||!clearActive)return;
    const items=Object.entries(filterNames).flatMap(([key,label])=>{
      const control=controls[key],value=control.value.trim();
      if(!value||value==='all')return [];
      const selected=control.tagName==='SELECT'
        ?control.selectedOptions[0]?.textContent||value:value;
      return [{key,label,value:selected}];
    });
    if(savedOnly)items.push({key:'saved',label:'Favoris',value:'uniquement'});
    activeFilters.hidden=items.length===0;
    // Keep a pressed pill attached through blur/change. Replacing it during
    // the pointer sequence can swallow the click on Android/mobile browsers.
    const signature=JSON.stringify(items);
    if(signature===activeFilterSignature)return;
    activeFilterSignature=signature;
    const chips=items.map(({key,label,value})=>{
      const chip=node('button',label+' : '+value+' ×','ud-filter-chip');
      chip.type='button';
      chip.dataset.removeFilter=key;
      chip.setAttribute('aria-label','Retirer le filtre '+label+' : '+value);
      return chip;
    });
    activePills.replaceChildren(...chips);
  };
  activePills?.addEventListener('click',event=>{
    const chip=event.target.closest('button[data-remove-filter]');
    if(!chip)return;
    const key=chip.dataset.removeFilter;
    if(key==='saved')savedOnly=false;
    else if(Object.hasOwn(filterNames,key))
      controls[key].value=key==='q'?'':'all';
    render();
    // Removing the pressed chip must not strand keyboard focus on <body>.
    (key==='saved'?savedToggle:controls[key])?.focus({preventScroll:true});
  });
  clearActive?.addEventListener('click',()=>{
    for(const key of Object.keys(filterNames))
      controls[key].value=key==='q'?'':'all';
    savedOnly=false;
    render();
    controls.q.focus({preventScroll:true});
  });
  const updateSavedUI=()=>{
    const count=cards.filter(card=>saved.has(card.dataset.id)).length;
    savedCount.textContent=String(count);
    savedToggle.setAttribute('aria-pressed',String(savedOnly));
    savedButtonLabel.textContent=savedOnly?'Voir toutes les montres':'Voir mes favoris';
    for(const card of cards){
      const button=card.querySelector('button.ud-save');
      if(!button)continue;
      const active=saved.has(card.dataset.id);
      const p=watches.get(card.dataset.id);
      button.setAttribute('aria-pressed',String(active));
      button.setAttribute('aria-label','Favoris : '+(active?'retirer ':'ajouter ')+(p?.brand||'')+' '+(p?.model||''));
      const heart=button.querySelector('.ud-save-heart');
      const word=button.querySelector('.ud-save-word');
      if(heart)heart.textContent=active?'♥':'♡';
      if(word)word.textContent='Favoris';
    }
  };
  const render=()=>{
    const q=normalized(controls.q.value),brand=controls.brand.value,
      style=controls.style.value,movement=controls.movement.value,
      tier=controls.tier.value,size=controls.size.value,visual=controls.visual.value,
      merchant=controls.merchant.value;
    const tokens=q.split(' ').filter(Boolean);
    let visible=0;
    for(const card of cards){
      const p=watches.get(card.dataset.id);
      const ok=Boolean(p)
        &&(!savedOnly||saved.has(p.id))
        &&(brand==='all'||p.brand===brand)
        &&(style==='all'||p.style===style)
        &&(movement==='all'||p.movement===movement)
        &&(tier==='all'||p.tier===tier)
        &&matchSize(p,size)
        &&(merchant==='all'||(p.merchantKind||'official')===merchant)
        &&(visual==='all'||(visual==='photo'&&Boolean(p.photoUrl))
          ||(visual==='no-photo'&&!p.photoUrl))
        &&matchesText(p,tokens);
      card.hidden=!ok;
      if(ok)visible++;
    }
    reorderCards(controls.sort.value);
    status.textContent=visible+' modèle'+(visible===1?'':'s')+' sur '+cards.length
      +(savedOnly?' · Mes favoris':'');
    empty.textContent=savedOnly?'Aucun favori ne correspond à ces critères. Enregistrez des montres avec le cœur, ou affichez tout le catalogue.'
      :'Aucun résultat. Essayez une autre marque, un style différent ou effacez les filtres.';
    empty.hidden=visible!==0;
    const endSummary=$('udResultsEndSummary');
    const endNavigation=endSummary?.closest('.ud-results-end');
    if(endSummary&&endNavigation){
      endNavigation.hidden=visible===0;
      endSummary.textContent=visible===cards.length
        ?'Vous avez parcouru les '+cards.length+' références de cette sélection.'
        :'Vous avez parcouru '+visible+' référence'+(visible===1?'':'s')
          +' correspondant à vos critères sur '+cards.length+'.';
    }
    updateSavedUI();
    updateActiveFilters();
    persist();
  };
  // Narrow Android screens benefit from photographs large enough to inspect
  // without opening every detail sheet. Respect a user-controlled preference;
  // a URL view parameter can override it for a shared catalogue link.
  const VIEW_KEY='atelier-montres-catalogue-view-v1';
  const storedView=()=>{
    try{
      const value=localStorage.getItem(VIEW_KEY);
      return value==='grid'||value==='large'?value:null;
    }catch(_){return null}
  };
  const changeView=(mode,remember=false)=>{
    view=mode==='large'?'large':'grid';
    root.classList.toggle('ud-view-large',view==='large');
    viewCompact.setAttribute('aria-pressed',String(view==='grid'));
    viewLarge.setAttribute('aria-pressed',String(view==='large'));
    if(remember){
      try{localStorage.setItem(VIEW_KEY,view)}catch(_){}
    }
    persist();
  };
  // A real, shareable 52-watch search link. Personal favourites stay local
  // and must never be misrepresented as a portable selection.
  const installShareTools=()=>{
    const tools=node('div',null,'ud-share-tools');
    tools.id='udShareTools';
    const button=node('button','Partager cette sélection');
    button.id='udShareSelection';
    button.type='button';
    const message=node('span',null,'ud-share-status');
    message.id='udShareStatus';
    message.setAttribute('role','status');
    message.setAttribute('aria-live','polite');
    const manual=node('input');
    manual.id='udShareManualLink';
    manual.type='url';
    manual.readOnly=true;
    manual.hidden=true;
    manual.setAttribute('aria-label','Lien de votre sélection à copier');
    tools.append(button,message,manual);
    viewTools.after(tools);
    button.addEventListener('click',async()=>{
      manual.hidden=true;
      if(savedOnly){
        message.textContent='Les favoris restent sur cet appareil. Affichez toutes les montres pour partager vos filtres.';
        return;
      }
      // render() has already synced the validated filters and model IDs to
      // history; the anchor opens at actual results, or the comparison table.
      const url=new URL(location.href);
      url.searchParams.delete('saved');
      if(url.hash!=='#comparer'||selected.length<2)url.hash='udCount';
      const shareUrl=url.href;
      message.textContent='';
      if(typeof navigator.share==='function'){
        try{
          await navigator.share({title:'Sélection de montres — Atelier Montres',url:shareUrl});
          message.textContent='Sélection partagée.';
          return;
        }catch(error){
          if(error?.name==='AbortError')return;
        }
      }
      if(navigator.clipboard?.writeText){
        try{
          await navigator.clipboard.writeText(shareUrl);
          message.textContent='Lien de sélection copié.';
          return;
        }catch(_){}
      }
      manual.value=shareUrl;
      manual.hidden=false;
      manual.focus();
      manual.select();
      message.textContent='Sélectionnez et copiez le lien pour partager cette sélection.';
    });
  };
  viewCompact.addEventListener('click',()=>changeView('grid',true));
  viewLarge.addEventListener('click',()=>changeView('large',true));
  savedToggle.addEventListener('click',()=>{
    savedOnly=!savedOnly;
    render();
  });
  const link=(label,url)=>{
    const a=node('a',label);a.href=url;return a;
  };
  const updateTray=()=>{
    // No-JS browsing remains untouched: the dock is revealed only after the
    // verified 52-watch JSON has been loaded and a real ID is selected.
    tray.hidden=selected.length===0;
    catalogue.classList.toggle('ud-has-tray',selected.length>0);
    trayCount.textContent=selected.length===1
      ?'1 sur 3 · ajoutez une deuxième montre'
      :selected.length+' sur 3 modèles sélectionnés';
    trayOpen.hidden=selected.length<2;
    trayOpen.textContent=selected.length>=2
      ?'Comparer '+selected.length+' montres':'Voir la comparaison';
    const nodes=selected.map(id=>{
      const p=watches.get(id),li=node('li',null,'ud-tray-item');
      if(!p)return li;
      li.append(node('span',p.brand+' '+p.model,'ud-tray-name'));
      const remove=node('button','×','ud-tray-remove');
      remove.type='button';remove.dataset.trayRemove=id;
      remove.setAttribute('aria-label','Retirer '+p.brand+' '+p.model+' de la comparaison');
      li.append(remove);return li;
    });
    trayItems.replaceChildren(...nodes);
  };
  const renderCompare=()=>{
    updateTray();
    compareStatus.textContent=selected.length===0?'Sélectionnez au moins deux modèles.'
      :selected.length===1?'Une montre choisie ; ajoutez-en une deuxième.'
      :selected.length+' montres choisies. Les informations inconnues sont affichées comme « Non documenté ».';
    compareClear.hidden=selected.length===0;
    for(const card of cards){
      const button=card.querySelector('button.ud-select');
      if(!button)continue;
      const active=selected.includes(card.dataset.id);
      button.setAttribute('aria-pressed',String(active));
      button.textContent=active?'Retirer de la comparaison':'Ajouter à la comparaison';
    }
    if(selected.length<2){
      if(decisionForm)decisionForm.hidden=true;
      compareTable.replaceChildren();compareTable.hidden=true;persist();return;
    }
    if(decisionForm&&decisionEngine)decisionForm.hidden=false;
    const decisionEntries=decisionEngine&&decisionPrefs
      ?decisionEngine.recommend(selected.map(id=>watches.get(id)),decisionPrefs,3):[];
    const scored=new Map(decisionEntries.map(entry=>[entry.product.id,entry]));
    const activeCriteria=decisionEntries[0]?.criteria||0;
    const rows=[
      ['Mouvement',p=>({quartz:'Quartz',automatic:'Automatique','eco-drive':'Solaire'})[p.movement]],
      ['Boîtier',p=>p.caseText],
      ['Diamètre du boîtier rond',p=>p.diameterMm===null?'Non documenté':p.diameterMm+' mm'],
      ['Verre',p=>p.glass],
      ['Étanchéité',p=>p.water],
      ['Style',p=>({sport:'Sport',classic:'Élégant',minimal:'Minimaliste',retro:'Rétro',statement:'Audacieux'})[p.style]]
    ];
    const table=node('table',null,'ud-matrix'),caption=node('caption','Comparaison de '+selected.length+' références documentées');
    const thead=node('thead'),heading=node('tr'),title=node('th','Critère');
    title.scope='col';heading.append(title);
    for(const id of selected){
      const p=watches.get(id),th=node('th');th.scope='col';
      // Only show an exact-model photograph already approved and stored
      // locally. Never silently substitute a different watch or remote image.
      const expected='./assets/'+(p.kind==='core'?'watches':'watches-popular')+'/'+p.id+'.webp';
      if(p.photoUrl===expected){
        const visual=node('div',null,'ud-matrix-photo');
        const img=node('img');
        img.src='../assets/'+(p.kind==='core'?'watches':'watches-popular')+'/'+p.id+'.webp';
        img.alt='Photographie du modèle '+p.brand+' '+p.model;
        img.loading='lazy';img.decoding='async';img.width=180;img.height=180;
        img.onerror=()=>visual.remove();
        visual.append(img);th.append(visual);
      }
      th.append(link(p.brand+' '+p.model,'./'+id+'.html'));
      const evaluation=scored.get(id);
      if(activeCriteria&&evaluation){
        const note=node('span',evaluation.matched+' / '+evaluation.criteria+
          ' critères concordants','ud-decision-score');
        note.dataset.match=evaluation.matched===evaluation.criteria?'exact'
          :evaluation.matched?'partial':'none';
        note.title=[...evaluation.details,evaluation.sizeNote].filter(Boolean).join(' · ')
          ||'Aucun critère vérifié parmi vos préférences';
        th.append(note);
        if(evaluation.details.length)
          th.append(node('small',evaluation.details.join(' · '),'ud-decision-reasons'));
        if(evaluation.sizeNote)
          th.append(node('small',evaluation.sizeNote,'ud-decision-warning'));
      }
      const remove=node('button','Retirer','ud-compare-remove');
      remove.type='button';remove.setAttribute('aria-label','Retirer '+p.brand+' '+p.model);
      remove.addEventListener('click',()=>{selected=selected.filter(x=>x!==id);renderCompare()});
      th.append(remove);heading.append(th);
    }
    thead.append(heading);
    const tbody=node('tbody');
    let differingCount=0;
    for(const [label,resolve] of rows){
      const values=selected.map(id=>resolve(watches.get(id))||'Non documenté');
      // Never treat unavailable measurements as an actual difference.
      const verified=values.filter(value=>value!=='Non documenté');
      const differing=new Set(verified).size>1;
      if(differing)differingCount++;
      const tr=node('tr'),th=node('th',label);th.scope='row';
      if(differing)tr.classList.add('ud-matrix-diff');
      tr.append(th);
      for(const value of values)tr.append(node('td',value));
      tbody.append(tr);
    }
    const hint=node('p',
      differingCount
        ?differingCount+' caractéristique'+(differingCount>1?'s':'')+
          ' différenciant vos montres. Les valeurs inconnues ne sont jamais considérées comme une différence.'
        :'Aucune différence documentée entre ces modèles sur les critères présentés.',
      'ud-matrix-hint');
    hint.id='udCompareHint';
    table.append(caption,thead,tbody);
    const summaries=[hint];
    if(activeCriteria){
      const exact=decisionEntries.filter(e=>e.matched===e.criteria).length;
      const count=selected.length;
      const text=exact===0
        ?'Aucune des '+count+' montres ne répond à toutes vos '+activeCriteria+
          ' préférences. Les modèles restent des alternatives, et les données inconnues ne sont pas des correspondances.'
        :exact+' montre'+(exact>1?'s':'')+' sur '+count+
          ' répond'+(exact>1?'ent':'')+' à toutes vos '+activeCriteria+
          ' préférences documentées.';
      const result=node('p',text,'ud-decision-result');
      result.id='udDecisionResult';
      result.dataset.status=exact?'matched':'none';
      result.setAttribute('aria-live','polite');
      summaries.unshift(result);
    }
    compareTable.replaceChildren(...summaries,table);compareTable.hidden=false;
    persist();
  };
  decisionForm?.addEventListener('submit',event=>event.preventDefault());
  decisionForm?.addEventListener('change',()=>{
    if(!decisionEngine)return;
    decisionPrefs=decisionEngine.choices(Object.fromEntries(
      prefKeys.map(key=>[key,prefControls[key]?.value||'all'])));
    renderCompare();
  });
  decisionReset?.addEventListener('click',()=>{resetDecision();renderCompare()});
  root.addEventListener('click',event=>{
    const zoom=event.target.closest('button.ud-zoom[data-zoom-id]');
    if(zoom){
      const id=zoom.dataset.zoomId,p=watches.get(id);
      if(!p?.photoUrl||!window.AtelierPhoto?.open)return;
      const photos=[...watches.values()].filter(q=>q.photoUrl
        &&q.photoUrl==='./assets/'+(q.kind==='core'?'watches':'watches-popular')+'/'+q.id+'.webp')
        .map(q=>({id:q.id,brand:q.brand,model:q.model,officialUrl:q.officialUrl,
          photoReview:{publicUsageApproved:true,localUrl:q.photoUrl}}));
      window.AtelierPhoto.open(photos,id,{assetPrefix:'../'});
      return;
    }
    const favourite=event.target.closest('button.ud-save[data-save-id]');
    if(favourite){
      const id=favourite.dataset.saveId;
      if(!watches.has(id))return;
      if(saved.has(id))saved.delete(id);else saved.add(id);
      try{localStorage.setItem(FAVORITES_KEY,JSON.stringify([...saved]))}catch(_){}
      render();
      return;
    }
    const btn=event.target.closest('button.ud-select[data-compare-id]');
    if(!btn)return;
    const id=btn.dataset.compareId;
    if(!watches.has(id))return;
    if(selected.includes(id))selected=selected.filter(x=>x!==id);
    else if(selected.length>=3){compareStatus.textContent='Trois modèles maximum. Retirez-en un avant d’en ajouter un quatrième.';return}
    else selected.push(id);
    renderCompare();
  });
  compareClear.addEventListener('click',()=>{selected=[];resetDecision();renderCompare()});
  trayClear.addEventListener('click',()=>{selected=[];resetDecision();renderCompare()});
  trayItems.addEventListener('click',event=>{
    const btn=event.target.closest('button[data-tray-remove]');
    if(!btn||!selected.includes(btn.dataset.trayRemove))return;
    selected=selected.filter(id=>id!==btn.dataset.trayRemove);
    renderCompare();
  });
  trayOpen.addEventListener('click',()=>{
    if(selected.length<2)return;
    // The native anchor scrolls to the real comparison. Focusing its scroll
    // region makes keyboard and screen-reader navigation immediately useful.
    compareTable.focus({preventScroll:true});
  });
  form.addEventListener('input',render);
  form.addEventListener('change',render);
  form.addEventListener('reset',()=>{requestAnimationFrame(()=>{savedOnly=false;render()})});
  // Returning from a 15-watch detail page through the Android back button
  // can restore the page from bfcache; refresh favourites without reloading.
  window.addEventListener('pageshow',()=>{
    saved=loadSaved();
    if(watches.size)render();
  });
  window.addEventListener('storage',event=>{
    if(event.key!==FAVORITES_KEY)return;
    saved=loadSaved();
    if(watches.size)render();
  });
  fetch('../discovery-catalogue.json',{cache:'no-store'}).then(r=>{
    if(!r.ok)throw Error('Catalogue indisponible');return r.json();
  }).then(data=>{
    if(data?.version!==1||data.total!==52||!Array.isArray(data.products)||data.products.length!==52)
      throw Error('Catalogue incomplet');
    watches=new Map(data.products.filter(p=>validId(p.id)).map(p=>[p.id,p]));
    if(watches.size!==52||cards.length!==52||cards.some(c=>!watches.has(c.dataset.id)))
      throw Error('Les fiches visibles ne correspondent pas aux références documentées');
    form.hidden=false;
    viewTools.hidden=false;
    favoriteTools.hidden=false;
    installShareTools();
    for(const card of cards){
      card.querySelector('button.ud-save')?.removeAttribute('hidden');
      card.querySelector('button.ud-select')?.removeAttribute('hidden');
      if(window.AtelierPhoto?.open)
        card.querySelector('button.ud-zoom')?.removeAttribute('hidden');
    }
    const requestedView=params.get('view');
    const selectedView=requestedView==='grid'||requestedView==='large'
      ?requestedView
      :storedView()||(window.matchMedia('(max-width: 480px)').matches?'large':'grid');
    changeView(selectedView);
    const initial=params.get('compare')?.split(',').filter(validId)||[];
    selected=[...new Set(initial)].filter(x=>watches.has(x)).slice(0,3);
    render();renderCompare();
    if(selected.length>=2&&location.hash==='#comparer')$('comparer')?.scrollIntoView();
  }).catch(()=>{
    // Progressive enhancement: all 52 static cards remain available. Never
    // display a broken filter or non-functioning compare button.
    root.querySelectorAll('.ud-card').forEach(c=>{c.hidden=false});
    status.textContent='52 modèles à consulter · filtres momentanément indisponibles';
  });
})();

/* Source-backed recent watch showroom: approved local photos only, zero remote assets.
   Cards can scroll inside their rail without creating horizontal page overflow. */
.am-unified-recent[hidden],
.am-unified-recent-compare[hidden],
.am-unified-recent-compare-link[hidden]{display:none!important}
.am-unified-recent{
  margin:24px 0 28px;padding:clamp(17px,2.5vw,28px);
  border:1px solid #c5d3c4;border-radius:9px;
  background:linear-gradient(145deg,#f6f8f3 0%,#fefcf5 66%,#f0f4ec 100%);
  box-shadow:0 12px 35px rgba(24,54,35,.06);color:#213c2b
}
.am-unified-recent-head{
  display:flex;align-items:flex-start;justify-content:space-between;
  gap:15px;flex-wrap:wrap;margin-bottom:17px
}
.am-unified-recent h2{
  font:400 clamp(23px,2.6vw,32px)/1.22 Georgia,serif;
  letter-spacing:-.025em;margin:0 0 6px;color:#193b29
}
.am-unified-recent p{
  font:450 12px/1.6 system-ui,sans-serif;margin:0;color:#49634e
}
.am-unified-recent-clear,.am-unified-recent-reset{
  min-height:44px;padding:10px 14px;background:#fffefa;
  border:1px solid #90a88e;border-radius:5px;color:#244c34;
  font:700 12px/1.5 system-ui,sans-serif;cursor:pointer
}
.am-unified-recent-clear:hover,.am-unified-recent-reset:hover{background:#e9f0e6}
.am-unified-recent-list{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));
  gap:13px;min-width:0
}
.am-unified-recent-item{
  display:flex;flex-direction:column;min-width:0;overflow:hidden;
  border:1px solid #d5ded1;border-radius:7px;
  background:#fffefa;box-shadow:0 4px 18px rgba(20,52,29,.055);
  transition:border-color .15s ease,transform .15s ease,box-shadow .15s ease
}
.am-unified-recent-item:hover{
  border-color:#9cad92;box-shadow:0 9px 25px rgba(20,52,29,.11);
  transform:translateY(-2px)
}
.am-unified-recent-link{
  display:flex;flex:1;flex-direction:column;min-width:0;
  color:#203f2c;text-decoration:none
}
.am-unified-recent-media{
  position:relative;display:grid;place-items:center;overflow:hidden;
  width:100%;height:clamp(118px,15vw,165px);padding:8px;
  background:radial-gradient(ellipse at 50% 48%,#fff 10%,#e9eee6 100%);
  border-bottom:1px solid #e2e8dc
}
.am-unified-recent-media img{
  display:block;max-width:100%;width:100%;height:100%;
  object-fit:contain;object-position:center;
  filter:drop-shadow(0 7px 8px rgba(20,43,26,.13))
}
.am-unified-recent-visual-label{
  position:absolute;bottom:6px;left:7px;
  padding:3px 7px;border-radius:3px;background:rgba(254,255,252,.92);
  color:#365a3e;font:700 9px/1.35 system-ui,sans-serif
}
.am-unified-recent-media-fallback{
  padding:15px;background:
    radial-gradient(ellipse at 70% 15%,rgba(215,197,146,.28),transparent 51%),
    linear-gradient(140deg,#1e3d2d,#2b5640 60%,#183628);
  border-bottom:1px solid #456b51;color:#f9f5e8
}
.am-unified-recent-fallback{
  display:flex;flex-direction:column;gap:8px;align-items:flex-start;
  justify-content:center;width:100%;height:100%;
  border:1px solid rgba(235,227,200,.26);padding:12px 14px;
  background:rgba(0,0,0,.055)
}
.am-unified-recent-fallback small{
  color:#c5d7bd;letter-spacing:.09em;
  font:750 9px/1.5 system-ui,sans-serif
}
.am-unified-recent-fallback strong{
  color:#fff9e6;overflow-wrap:anywhere;
  font:400 clamp(17px,2vw,23px)/1.2 Georgia,serif
}
.am-unified-recent-fallback span{
  font:500 10px/1.5 system-ui,sans-serif;color:#d4dfd0
}
.am-unified-recent-info{
  display:flex;flex-direction:column;gap:6px;padding:12px 13px 14px;
  min-height:100px
}
.am-unified-recent-range{
  color:#607b62;font:750 10px/1.35 system-ui,sans-serif;
  letter-spacing:.045em;text-transform:uppercase
}
.am-unified-recent-name{
  font:700 13px/1.42 system-ui,sans-serif;color:#20432f;
  overflow-wrap:anywhere
}
.am-unified-recent-see{
  margin-top:auto;padding-top:3px;
  font:700 11px/1.4 system-ui,sans-serif;color:#4c7453
}
.am-unified-recent-pick{
  display:block;min-height:44px;width:100%;
  padding:9px 12px;border:0;border-top:1px solid #d6e0d3;
  background:#eef4ea;color:#2c5134;cursor:pointer;
  font:750 11px/1.45 system-ui,sans-serif;text-align:center
}
.am-unified-recent-pick:hover{background:#e2eee0}
.am-unified-recent-pick[aria-pressed="true"]{
  background:#245439;color:#fff
}
.am-unified-recent-compare{
  display:flex;align-items:center;flex-wrap:wrap;gap:12px;
  margin-top:16px;padding:13px 16px;border-radius:5px;
  border:1px solid #b9cbb4;background:#eaf1e7
}
.am-unified-recent-compare-status{
  flex:1 1 160px;font:700 12px/1.5 system-ui,sans-serif!important
}
.am-unified-recent-compare-link{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:44px;padding:10px 16px;border-radius:5px;
  background:#21523a;color:#fff;text-decoration:none;
  font:750 13px/1.45 system-ui,sans-serif
}
.am-unified-recent-compare-link:hover{background:#133b28}
.am-unified-recent-clear:focus-visible,
.am-unified-recent-reset:focus-visible,
.am-unified-recent-link:focus-visible,
.am-unified-recent-pick:focus-visible,
.am-unified-recent-compare-link:focus-visible{
  outline:3px solid #b78b45;outline-offset:2px
}
@media(max-width:950px){
  .am-unified-recent-list{grid-template-columns:repeat(2,minmax(0,1fr))}
  .am-unified-recent-media{height:150px}
}
@media(max-width:600px){
  .am-unified-recent{padding:16px 0 14px}
  .am-unified-recent-head{margin:0 15px 14px}
  .am-unified-recent-list{
    display:flex;gap:12px;overflow-x:auto;overscroll-behavior-inline:contain;
    scroll-snap-type:x proximity;scroll-padding-inline:15px;
    padding:0 15px 13px;-webkit-overflow-scrolling:touch
  }
  .am-unified-recent-item{
    flex:0 0 min(77vw,274px);
    scroll-snap-align:start
  }
  .am-unified-recent-media{height:155px}
  .am-unified-recent-head .am-unified-recent-clear{width:100%}
  .am-unified-recent-compare{
    margin:4px 15px 0;align-items:stretch
  }
  .am-unified-recent-compare-link{flex:1 1 100%}
  .am-unified-recent-reset{flex:1 1 100%}
}
@media(prefers-reduced-motion:reduce){
  .am-unified-recent-item{transition:none}
  .am-unified-recent-item:hover{transform:none}
}

'use strict';
/*
 * Eight recent exact-model references, stored only on the visitor's device.
 * Premium source-derived thumbnails and a direct path to the existing factual
 * comparison. Never fetch third-party images or infer prices/availability.
 */
(() => {
  const key='atelier-montres-unified-recent-v1';
  const valid=id=>typeof id==='string'&&/^[a-z0-9-]{4,64}$/.test(id);
  const read=()=>{
    try{
      const raw=JSON.parse(localStorage.getItem(key)||'[]');
      return Array.isArray(raw)?[...new Set(raw.filter(valid))].slice(0,8):[];
    }catch{return null;}
  };
  const article=document.querySelector('main article.watch-product[data-watch-id],main article.am-extra-product[data-popular-watch-id]');
  if(article){
    const id=article.dataset.watchId||article.dataset.popularWatchId;
    const brand=article.dataset.brand,model=article.dataset.model;
    if(!valid(id)||!brand||!model||article.querySelector('h1')?.textContent?.trim()!==brand+' '+model
      ||location.pathname!=='/montres/'+id+'.html')return;
    const ids=read();
    if(ids===null)return;
    try{localStorage.setItem(key,JSON.stringify([id,...ids.filter(x=>x!==id)].slice(0,8)));}catch{}
    return;
  }
  const grid=document.querySelector('#udGrid');
  const section=document.querySelector('[data-unified-recent]');
  const list=section?.querySelector('[data-unified-recent-list]');
  const clear=section?.querySelector('[data-unified-recent-clear]');
  if(!grid||!section||!list||!clear)return;
  const cards=new Map([...grid.querySelectorAll('article.ud-card[data-id]')]
    .filter(card=>valid(card.dataset.id)&&card.dataset.brand&&card.dataset.model
      &&card.querySelector('h2')?.textContent?.trim()===card.dataset.brand+' '+card.dataset.model)
    .map(card=>[card.dataset.id,card]));
  if(cards.size!==52)return;

  const text=(tag,value,cls)=>{
    const element=document.createElement(tag);
    if(value!==null)element.textContent=value;
    if(cls)element.className=cls;
    return element;
  };
  // Permit only the exact source image from this model and local, generated
  // responsive derivatives. Never copy arbitrary image URLs out of the DOM.
  const localAsset=(raw,id)=>{
    try{
      const url=new URL(raw,location.href);
      if(url.origin!==location.origin||url.hash||url.username||url.password)return false;
      // The build appends a SHA-256 cache key to approved responsive WebPs.
      // Keep only that exact syntax; arbitrary URLs and query strings remain blocked.
      if(url.search&&!/^\?v=[a-f0-9]{12}$/.test(url.search))return false;
      return url.pathname==='/assets/watches/'+id+'.webp'
        ||url.pathname==='/assets/watches-popular/'+id+'.webp'
        ||new RegExp('^/assets/(?:watch-responsive|popular-responsive)/'+id+'-[0-9]+\\.webp$').test(url.pathname);
    }catch{return false;}
  };
  const photoFor=(card,id)=>{
    if(card.dataset.visual!=='photo')return null;
    const source=card.querySelector('.ud-photo img');
    if(!source||!localAsset(source.getAttribute('src'),id))return null;
    const img=document.createElement('img');
    img.src=source.getAttribute('src');
    const originalSet=source.getAttribute('srcset')||'';
    if(originalSet){
      const candidates=originalSet.split(',').map(piece=>piece.trim().split(/\s+/));
      if(candidates.every(parts=>parts.length===2&&/^[1-9][0-9]*w$/.test(parts[1])
        &&localAsset(parts[0],id)))img.srcset=originalSet;
    }
    img.sizes='(max-width: 700px) 140px, 220px';
    img.width=220;
    img.height=160;
    img.loading='lazy';
    img.decoding='async';
    img.alt=''; // Adjacent exact-model text labels the whole linked card.
    return img;
  };

  const actions=text('div',null,'am-unified-recent-compare');
  actions.hidden=true;
  const message=text('p','', 'am-unified-recent-compare-status');
  message.setAttribute('role','status');
  message.setAttribute('aria-live','polite');
  const compareLink=text('a','Comparer les montres','am-unified-recent-compare-link');
  compareLink.hidden=true;
  const reset=text('button','Réinitialiser la sélection','am-unified-recent-reset');
  reset.type='button';
  actions.append(message,compareLink,reset);
  list.after(actions);
  let chosen=[];

  const updateCompare=()=>{
    chosen=chosen.filter(id=>cards.has(id)&&list.querySelector('[data-recent-watch-id="'+id+'"]'));
    for(const button of list.querySelectorAll('button[data-recent-compare-id]')){
      const id=button.dataset.recentCompareId;
      const selected=chosen.includes(id);
      button.setAttribute('aria-pressed',String(selected));
      button.textContent=selected?'Retirer de la comparaison':'Sélectionner pour comparer';
      const card=cards.get(id);
      button.setAttribute('aria-label',button.textContent+' '
        +(card?.dataset.brand||'')+' '+(card?.dataset.model||''));
    }
    actions.hidden=chosen.length===0;
    message.textContent=chosen.length===1?'Une montre choisie. Sélectionnez-en une deuxième.'
      :chosen.length+' montres sélectionnées sur 3 maximum.';
    compareLink.hidden=chosen.length<2;
    if(chosen.length>=2){
      compareLink.href='?compare='+chosen.join(',')+'#comparer';
      compareLink.textContent='Comparer '+chosen.length+' montres';
    }else compareLink.removeAttribute('href');
  };

  const render=()=>{
    const ids=read();
    list.replaceChildren();
    if(!ids){chosen=[];actions.hidden=true;section.hidden=true;return;}
    for(const id of ids){
      const card=cards.get(id);
      if(!card)continue;
      const item=text('article',null,'am-unified-recent-item');
      item.dataset.recentWatchId=id;
      const link=text('a',null,'am-unified-recent-link');
      link.href='./'+id+'.html';
      const media=text('span',null,'am-unified-recent-media');
      const photo=photoFor(card,id);
      if(photo){
        media.append(photo);
        media.append(text('span','Photo du modèle','am-unified-recent-visual-label'));
      }else{
        media.classList.add('am-unified-recent-media-fallback');
        const fallback=text('span',null,'am-unified-recent-fallback');
        fallback.append(text('small','PHOTO NON PUBLIÉE'),
          text('strong',card.dataset.brand),text('span','Voir la fiche de la marque'));
        media.append(fallback);
      }
      const details=text('span',null,'am-unified-recent-info');
      const range=card.querySelector('.ud-tier-pill')?.textContent?.trim()||'Sélection documentée';
      details.append(text('small',range,'am-unified-recent-range'),
        text('strong',card.dataset.brand+' '+card.dataset.model,'am-unified-recent-name'),
        text('span','Voir la fiche et les sources','am-unified-recent-see'));
      link.append(media,details);
      const pick=text('button','Sélectionner pour comparer','am-unified-recent-pick');
      pick.type='button';
      pick.dataset.recentCompareId=id;
      pick.setAttribute('aria-pressed','false');
      item.append(link,pick);
      list.append(item);
    }
    section.hidden=!list.childElementCount;
    updateCompare();
  };
  list.addEventListener('click',event=>{
    const button=event.target.closest('button[data-recent-compare-id]');
    if(!button||!list.contains(button))return;
    const id=button.dataset.recentCompareId;
    if(!cards.has(id)||!list.querySelector('[data-recent-watch-id="'+id+'"]'))return;
    if(chosen.includes(id))chosen=chosen.filter(value=>value!==id);
    else if(chosen.length<3)chosen.push(id);
    else{
      actions.hidden=false;
      message.textContent='Trois montres maximum. Retirez-en une avant d’en ajouter une autre.';
      return;
    }
    updateCompare();
  });
  reset.addEventListener('click',()=>{chosen=[];updateCompare();});
  clear.addEventListener('click',()=>{
    try{localStorage.removeItem(key);}catch{return;}
    chosen=[];
    render();
  });
  window.addEventListener('pageshow',render);
  window.addEventListener('storage',event=>{if(event.key===key)render();});
  render();
})();

/* Source-backed merchant entrypoints for the 52-watch public catalogue.
   Editorial counts only: no implied offer prices, stock, commission or sales. */
.ud-page .ud-paths{margin:36px 0 30px;padding:clamp(19px,3vw,33px);border:1px solid #d2dccc;border-radius:9px;background:linear-gradient(135deg,#f9faf4,#f1f3ea);color:#254434}
.ud-paths-header{display:flex;justify-content:space-between;align-items:end;gap:16px 36px;margin-bottom:19px}
.ud-paths-header>div{min-width:0;max-width:60%}
.ud-paths-header>div>span{display:block;margin-bottom:7px;color:#7e6142;text-transform:uppercase;letter-spacing:.11em;font:800 10px/1.5 system-ui,sans-serif}
.ud-paths-header h2{margin:0;font:400 clamp(26px,3.1vw,39px)/1.2 Georgia,serif;letter-spacing:-.03em;color:#1e3f2d;text-wrap:balance}
.ud-paths-header>p{max-width:43ch;margin:0;color:#485d4d;font:450 13px/1.7 system-ui,sans-serif}
.ud-path-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px}
.ud-path-link{--path-accent:#597d61;position:relative;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:215px;padding:18px;border:1px solid #cdd9cb;border-radius:6px;background:#fffefa;color:#254534;text-decoration:none;box-shadow:0 6px 20px rgba(31,57,35,.05);transition:border-color .18s ease,box-shadow .18s ease}
.ud-path-link[data-merchant-path="direct"]{--path-accent:#29734a;border-top:4px solid #29734a}
.ud-path-link[data-merchant-path="awin"]{--path-accent:#536d99;border-top:4px solid #536d99}
.ud-path-link[data-merchant-path="search"]{--path-accent:#967041;border-top:4px solid #967041}
.ud-path-link[data-merchant-path="official"]{--path-accent:#5e7770;border-top:4px solid #5e7770}
.ud-path-icon{position:absolute;top:14px;right:15px;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#eef2ea;color:var(--path-accent);font:750 20px/1 system-ui,sans-serif}
.ud-path-eyebrow{padding-right:27px;color:#546c56;letter-spacing:.04em;text-transform:uppercase;font:750 10px/1.45 system-ui,sans-serif}
.ud-path-link strong{display:block;max-width:22ch;font:400 clamp(21px,2.2vw,27px)/1.19 Georgia,serif;color:#21422f;letter-spacing:-.018em}
.ud-path-description{color:#516558;font:450 12px/1.6 system-ui,sans-serif}
.ud-path-count{display:inline-flex;justify-content:space-between;align-items:center;gap:9px;margin-top:auto;padding:10px 0 0;border-top:1px solid #dce2d8;color:#24503a;font:800 12px/1.5 system-ui,sans-serif}
.ud-path-link:hover{border-color:var(--path-accent);box-shadow:0 12px 30px rgba(24,55,31,.13)}
.ud-path-link:focus-visible{outline:3px solid #b68a44;outline-offset:3px}
.ud-paths-disclosure{max-width:103ch;margin:15px 0 0;color:#4f6153;font:450 12px/1.75 system-ui,sans-serif}
@media(max-width:850px){
 .ud-paths-header{display:block}
 .ud-paths-header>div{max-width:none}
 .ud-paths-header>p{margin-top:11px;max-width:70ch}
}
@media(max-width:650px){
 .ud-page .ud-paths{margin:27px 0 25px;padding:18px 15px}
 .ud-path-links{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x proximity;overscroll-behavior-x:contain;scrollbar-width:thin;scrollbar-color:#9aac9b #edf0e8;padding:3px 3px 14px;margin:0 -3px}
 .ud-path-link{flex:0 0 min(84%,310px);min-height:220px;scroll-snap-align:start}
}
@media(prefers-reduced-motion:reduce){.ud-path-link{transition:none}}

/* Atelier Montres · visual finishing for the public 52-watch collection.
 * Editorial ranges are NOT verified price brackets. No additional images,
 * fonts, scripts, merchant endpoints or remote resources. */
.ud-tier-navigation{margin:clamp(36px,5vw,66px) 0 35px;padding:0;min-width:0;color:#203e2d}
.ud-tier-navigation-head{display:flex;justify-content:space-between;align-items:end;gap:18px 35px;margin:0 0 22px}
.ud-tier-navigation-eyebrow{display:block;margin:0 0 10px;color:#866742;letter-spacing:.11em;text-transform:uppercase;font:800 11px/1.5 system-ui,sans-serif}
.ud-tier-navigation h2{margin:0;font:400 clamp(30px,4vw,48px)/1.13 Georgia,serif;letter-spacing:-.035em;color:#193b2a;text-wrap:balance}
.ud-tier-navigation-head>p{max-width:44ch;margin:0;color:#4a6250;font:400 14px/1.75 system-ui,sans-serif}
.ud-tier-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.ud-tier-shortcut{--tone:#8a8f70;min-width:0;display:flex;flex-direction:column;gap:10px;min-height:226px;padding:24px 23px 19px;position:relative;overflow:hidden;border:1px solid #d4d8c9;border-top:4px solid var(--tone);border-radius:7px;background:#fffcf5;color:#20412e;text-decoration:none;box-shadow:0 9px 27px rgba(24,51,31,.055);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.ud-tier-shortcut::after{content:"";position:absolute;right:-50px;top:-44px;width:155px;aspect-ratio:1;border:20px solid color-mix(in srgb,var(--tone),transparent 83%);border-radius:50%;pointer-events:none}
.ud-tier-shortcut[data-tier-shortcut="essential"]{--tone:#749779;background:linear-gradient(135deg,#f7faf4,#fffdf7)}
.ud-tier-shortcut[data-tier-shortcut="signature"]{--tone:#ab8754;background:linear-gradient(135deg,#fbf5e8,#fffdfa)}
.ud-tier-shortcut[data-tier-shortcut="prestige"]{--tone:#61788c;background:linear-gradient(135deg,#eff3f7,#fffdf8)}
.ud-tier-shortcut-index{position:relative;z-index:1;color:#4c6552;letter-spacing:.14em;font:750 10px/1.5 system-ui,sans-serif}
.ud-tier-shortcut strong{position:relative;z-index:1;font:400 clamp(23px,2.6vw,31px)/1.16 Georgia,serif;letter-spacing:-.025em}
.ud-tier-shortcut-desc{position:relative;z-index:1;color:#4b5e4e;font:450 13px/1.65 system-ui,sans-serif;max-width:35ch}
.ud-tier-shortcut-footer{position:relative;z-index:1;margin-top:auto;padding-top:12px;border-top:1px solid #cdd7ca;color:#23513a;font:750 12px/1.4 system-ui,sans-serif;display:flex;justify-content:space-between;gap:10px}
.ud-tier-shortcut-footer span{font-size:19px;line-height:1}
.ud-tier-shortcut:hover{border-color:var(--tone);box-shadow:0 16px 33px rgba(27,52,34,.12);transform:translateY(-3px)}
.ud-tier-shortcut:focus-visible{outline:3px solid #b88b44;outline-offset:4px}
.ud-tier-disclaimer{margin:13px 0 0;color:#5a6959;font:450 12px/1.7 system-ui,sans-serif}
/* Watch cards retain the existing source, comparison and commercial flows.
   A discrete collection signature helps shoppers compare at a glance. */
.ud-page .ud-grid{align-items:stretch}
.ud-page .ud-card{--card-accent:#829983;position:relative;border:1px solid #d4ddcf;border-radius:9px;box-shadow:0 10px 25px rgba(29,57,36,.067);transition:border-color .17s ease,box-shadow .17s ease;isolation:isolate}
.ud-page .ud-card[data-tier="essential"]{--card-accent:#618a70}
.ud-page .ud-card[data-tier="signature"]{--card-accent:#a67e43}
.ud-page .ud-card[data-tier="prestige"]{--card-accent:#55758c}
.ud-page .ud-card::before{content:"";height:4px;position:absolute;z-index:4;top:0;left:0;right:0;background:var(--card-accent);pointer-events:none}
.ud-page .ud-card:hover{border-color:#9bb5a0;box-shadow:0 17px 36px rgba(28,54,36,.13)}
.ud-page .ud-card-main{gap:11px}
.ud-page .ud-card .ud-kicker{display:flex;align-items:center;flex-wrap:wrap;gap:7px 9px;letter-spacing:normal;text-transform:none}
.ud-page .ud-tier-pill{display:inline-flex;align-items:center;min-height:27px;padding:5px 9px;border-radius:4px;border:1px solid color-mix(in srgb,var(--card-accent),white 55%);background:color-mix(in srgb,var(--card-accent),white 90%);color:#284633;font:800 10px/1.4 system-ui,sans-serif;letter-spacing:.018em}
.ud-page .ud-card[data-tier="signature"] .ud-tier-pill{color:#725328}
.ud-page .ud-card[data-tier="prestige"] .ud-tier-pill{color:#2c526c}
.ud-page .ud-card-style{font:600 11px/1.5 system-ui,sans-serif;color:#607062}
.ud-page .ud-card h2{letter-spacing:-.02em;text-wrap:pretty}
.ud-page .ud-description{color:#405c49}
.ud-page .ud-card-main>dl{padding:11px 12px;background:#f5f6f0;border:1px solid #e4e7dd;border-radius:5px;gap:11px}
.ud-page .ud-card-main>dl>div{padding-top:0;border:0}
.ud-page .ud-offer-context{border-radius:5px;overflow-wrap:anywhere}
.ud-page .ud-merchant-kind{max-width:100%;font-size:11px;line-height:1.45}
.ud-page .ud-card .ud-actions a{min-height:48px;border-radius:5px;line-height:1.5;padding:11px 12px;text-wrap:pretty;overflow-wrap:anywhere}
.ud-page .ud-card .ud-actions .ud-details{background:#244d35;color:#fff!important;border:1px solid #244d35}
.ud-page .ud-card .ud-actions .ud-details:hover{background:#345f45}
.ud-page .ud-card[data-merchant="direct"] .ud-actions .ud-merchant,
.ud-page .ud-card[data-merchant="awin"] .ud-actions .ud-merchant{background:#e8f0e5;border:1px solid #7ba183;color:#1e5033!important;font-weight:800}
.ud-page .ud-card[data-merchant="direct"] .ud-actions .ud-merchant:hover,
.ud-page .ud-card[data-merchant="awin"] .ud-actions .ud-merchant:hover{background:#dceadb}
